import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.codec.binary.Base64;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom filter: strip obvious attack patterns but allow legitimate queries
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove NULL bytes and control characters
        input = input.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]", "");
        // Collapse multiple spaces
        input = input.replaceAll("\\s+", " ").trim();
        return input;
    }

    // Validates report type against known patterns
    private boolean isValidReportType(String type) {
        return Pattern.matches("^[a-zA-Z_]{1,30}$", type);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation - must match YYYY-MM-DD
        if (!Pattern.matches("^\\d{4}-\\d{2}-\\d{2}$", dateFrom) ||
            !Pattern.matches("^\\d{4}-\\d{2}-\\d{2}$", dateTo)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column - sanitized but NOT validated against allowlist
        sortCol = sanitizeInput(sortCol);

        String query = "SELECT id, customer_name, amount, created_at FROM reports_" 
            + reportType + " WHERE created_at BETWEEN '" + dateFrom + "' AND '" 
            + dateTo + "' ORDER BY " + sortCol;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            StringBuilder output = new StringBuilder();
            if ("csv".equals(format)) {
                resp.setContentType("text/csv");
                for (int i = 1; i <= cols; i++) {
                    output.append(meta.getColumnName(i));
                    if (i < cols) output.append(",");
                }
                output.append("\n");
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        String val = rs.getString(i);
                        output.append(val != null ? val.replace(",", ";") : "");
                        if (i < cols) output.append(",");
                    }
                    output.append("\n");
                }
            } else {
                resp.setContentType("application/json");
                output.append("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) output.append(",\n");
                    output.append("  {");
                    for (int i = 1; i <= cols; i++) {
                        output.append("\"" + meta.getColumnName(i) + "\":");
                        output.append("\"" + (rs.getString(i) != null ? rs.getString(i).replace("\"", "\\\"") : "") + "\"");
                        if (i < cols) output.append(",");
                    }
                    output.append("}");
                    first = false;
                }
                output.append("\n]");
            }

            resp.getWriter().write(output.toString());

        } catch (SQLException e) {
            // Log full error for debugging
            log("Query failed: " + query + " Error: " + e.getMessage());
            resp.sendError(500, "Report generation failed: " + e.getSQLState());
        }
    }
}
